  add("realanalysis", "ra1", 2, [{"type":"regular","q":"Is \\(a_n = \\frac{1}{n}\\) a Cauchy sequence?","answer":"Yes","solution":"For any ε > 0, choose N > 2/ε; then for m, n ≥ N, \\(|a_m - a_n| \\leq 1/N < ε\\)."},{"type":"regular","q":"For the sequence \\(a_n = \\frac{n}{n+1}\\), verify it is Cauchy by estimating \\(|a_m - a_n|\\).","answer":"\\(|a_m - a_n| = \\frac{|m - n|}{(m+1)(n+1)}\\)","solution":"Compute the difference and note it shrinks as m, n grow large."},{"type":"regular","q":"Is \\(a_n = (-1)^n\\) a Cauchy sequence?","answer":"No","solution":"For large m, n with opposite parities, \\(|a_m - a_n| = 2\\), violating the Cauchy condition."},{"type":"regular","q":"If \\(a_n\\) is Cauchy, must it be bounded?","answer":"Yes","solution":"For ε = 1, all terms beyond some N lie within a bounded interval."},{"type":"regular","q":"In \\(\\mathbb{R}\\), a sequence is Cauchy if and only if it is what?","answer":"Convergent","solution":"This is the Cauchy completeness criterion for the real numbers."},{"type":"regular","q":"Is \\(a_n = \\sqrt{n}\\) a Cauchy sequence?","answer":"No","solution":"For large m, n, \\(|\\sqrt{m} - \\sqrt{n}|\\) can be arbitrarily large."},{"type":"regular","q":"Show that \\(a_n = \\frac{1}{2^n}\\) is Cauchy. What is the limit?","answer":"Limit is 0","solution":"For m > n, \\(|a_m - a_n| = \\frac{1}{2^n}(\\frac{1}{2^{m-n}} - 1) < \\frac{1}{2^n}\\), which tends to 0."},{"type":"regular","q":"Can a Cauchy sequence in \\(\\mathbb{Q}\\) fail to converge in \\(\\mathbb{Q}\\)?","answer":"Yes","solution":"\\(\\mathbb{Q}\\) is not complete; e.g., the decimal approximations of \\(\\sqrt{2}\\) form a Cauchy sequence in \\(\\mathbb{Q}\\) with no rational limit."},{"type":"word","q":"A sequence of measurements \\(a_n\\) is taken with increasing precision such that \\(|a_m - a_n| < 10^{-k}\\) whenever m, n > N_k. Is this a Cauchy sequence?","answer":"Yes","solution":"The condition directly matches the definition of a Cauchy sequence."},{"type":"word","q":"Two numerical methods produce sequences that get arbitrarily close to each other. Does this guarantee they both converge?","answer":"In \\(\\mathbb{R}\\), yes; in \\(\\mathbb{Q}\\), not necessarily","solution":"Cauchy sequences converge in complete spaces like \\(\\mathbb{R}\\) but not in incomplete spaces like \\(\\mathbb{Q}\\)."},{"type":"word","q":"A physicist records position measurements \\(x_n\\) such that successive measurements differ by less than \\(\\frac{1}{n^2}\\) meters. Is the sequence Cauchy?","answer":"Yes","solution":"The differences shrink fast enough to satisfy the Cauchy criterion."},{"type":"word","q":"An iterative algorithm produces a sequence where \\(|a_{n+1} - a_n| = 0.9^n\\). Is the sequence Cauchy?","answer":"Yes","solution":"The terms form a geometric series with ratio < 1, so differences vanish in the limit."},{"type":"word","q":"A sequence of rational approximations to π converges in \\(\\mathbb{R}\\). Is it Cauchy?","answer":"Yes","solution":"Every convergent sequence in \\(\\mathbb{R}\\) is Cauchy."},{"type":"regular","q":"If \\(\\{a_n\\}\\) is Cauchy and \\(\\{b_n\\}\\) is Cauchy, is \\(\\{a_n + b_n\\}\\) Cauchy?","answer":"Yes","solution":"\\(|(a_m + b_m) - (a_n + b_n)| \\leq |a_m - a_n| + |b_m - b_n|\\), both of which are small."},{"type":"regular","q":"In \\(\\mathbb{R}\\), does every Cauchy sequence have a limit?","answer":"Yes","solution":"The real numbers form a complete metric space."}]);
